import{I as p,o as t,c as o,b6 as n,J as r,w as h,j as s,a as l}from"./chunks/framework.BUXTSoD9.js";const g=JSON.parse('{"title":"استخدم Jobs to Be Done للعثور على ما يريد المستخدم إنجازه حقًا","description":"مقالة تمهيدية عن Jobs to Be Done للقراء بدون خبرة سابقة. فهم أن المستخدم لا يشتري الوظائف، بل \\"يوظف\\" منتجك في سيناريو محدد لإنجاز تقدم، وتعلم استخدام JTBD لتفكيك اتجاه المنتج وأسئلة المقابلة وتعليمات AI.","frontmatter":{"title":"استخدم Jobs to Be Done للعثور على ما يريد المستخدم إنجازه حقًا","description":"مقالة تمهيدية عن Jobs to Be Done للقراء بدون خبرة سابقة. فهم أن المستخدم لا يشتري الوظائف، بل \\"يوظف\\" منتجك في سيناريو محدد لإنجاز تقدم، وتعلم استخدام JTBD لتفكيك اتجاه المنتج وأسئلة المقابلة وتعليمات AI."},"headers":[],"relativePath":"ar-sa/stage-1/appendix-jobs-to-be-done/index.md","filePath":"ar-sa/stage-1/appendix-jobs-to-be-done/index.md"}'),d={name:"ar-sa/stage-1/appendix-jobs-to-be-done/index.md"},k=Object.assign(d,{setup(c){const i="حوالي <strong>1.5 ساعة</strong>";return(b,a)=>{const e=p("ChapterIntroduction");return t(),o("div",null,[a[1]||(a[1]=n('<h1 id="استخدم-jobs-to-be-done-للعثور-على-ما-يريد-المستخدم-إنجازه-حقًا" tabindex="-1">استخدم Jobs to Be Done للعثور على ما يريد المستخدم إنجازه حقًا <a class="header-anchor" href="#استخدم-jobs-to-be-done-للعثور-على-ما-يريد-المستخدم-إنجازه-حقًا" aria-label="Permalink to “استخدم Jobs to Be Done للعثور على ما يريد المستخدم إنجازه حقًا”">​</a></h1><p><a id="top-jtbd"></a></p><h2 id="دليل-هذا-الفصل" tabindex="-1">دليل هذا الفصل <a class="header-anchor" href="#دليل-هذا-الفصل" aria-label="Permalink to “دليل هذا الفصل”">​</a></h2>',3)),r(e,{duration:i,tags:["JTBD","احتياجات المستخدم","تفكير المنتج","رؤى المتطلبات"],coreOutput:"جملة JTBD واحدة تشبه الاحتياج الحقيقي",expectedOutput:"القدرة على تضييق الفكرة الغامضة إلى سيناريو مستخدم واتجاه MVP أكثر تحديدًا"},{default:h(()=>[...a[0]||(a[0]=[s("p",null,'العديد من الأشخاص عند بداية صنع المنتج، الخطأ الأكثر شيوعًا هو التركيز بالكامل على "ما الوظائف التي سأصنعها". ترى الآخرين لديهم تصنيف ذكي، فتريد إضافته؛ ترى الآخرين لديهم تلخيص تلقائي، فتريد توصيله؛ ترى الآخرين صنعوا Agent ووسائط متعددة وسير عمل، فتشعر بأنك لا يجب أن تكون أقل.',-1),s("p",null,'لكن في الواقع، نادرًا ما يقرر المستخدم استخدام منتج لأن "اسم الوظيفة رائع". هم في لحظة محددة، يريدون دفع شيء ما خطوة إلى الأمام، فيقومون مؤقتًا بـ "توظيف" أداة أو خدمة أو حتى شخص، لمساعدتهم في إكمال هذه الخطوة.',-1),s("p",null,[l("هذا بالضبط ما يريد إطار "),s("strong",null,"Jobs to Be Done (JTBD)"),l(" تذكيرنا به: "),s("strong",null,"المستخدم لا يشتري الوظائف نفسها، بل يوظف نوعًا من الحلول لمساعدة نفسه في إنجاز تقدم.")],-1),s("p",null,"هذه المقالة ستأخذك بلغة مباشرة قدر الإمكان، من الصفر لفهم JTBD، وتحويله إلى أداة تحليل يمكنك استخدامها مباشرة عند صنع تطبيقات AI.",-1)])]),_:1}),a[2]||(a[2]=n(`<div class="info custom-block"><p class="custom-block-title">الحد الأدنى من SOP</p><p><strong>الهدف</strong>: بعد القراءة، ستكون أكثر وضوحًا حول كيفية تضييق فكرة غامضة إلى احتياج بسيناريو مستخدم حقيقي، بدلاً من الاحتفاظ فقط بمجموعة من أسماء الوظائف في ذهنك.</p><p><strong>خطوات العمل</strong>: اكتب فكرة غامضة واحدة، ابحث عن 3 مستخدمين محتملين وتحدث معهم عن &quot;كيف تعاملوا مع الأمر آخر مرة&quot;، ثم نظّمها في جملة JTBD واحدة.</p><p><strong>النتيجة</strong>: ستحصل على فرضية احتياج أوضح، وتعرف ما يجب حله أولاً في النسخة الأولى.</p><p><strong>روابط سريعة</strong>: <a href="#jtbd-what">ما هو JTBD</a> · <a href="#jtbd-formula">صيغة الجملة الواحدة</a> · <a href="#jtbd-ai">كيف يساعدك AI</a></p></div><h2 id="ما-ستتعلمه-في-هذا-الفصل" tabindex="-1">ما ستتعلمه في هذا الفصل <a class="header-anchor" href="#ما-ستتعلمه-في-هذا-الفصل" aria-label="Permalink to “ما ستتعلمه في هذا الفصل”">​</a></h2><ol><li>ما هو Jobs to Be Done، ولماذا هو أقرب إلى الاحتياجات الحقيقية من &quot;عصف الوظائف&quot;</li><li>كيف نفرق بين &quot;الوظيفة التي يقول المستخدم أنه يريدها&quot; و&quot;ما يريد المستخدم إنجازه حقًا&quot;</li><li>كيف تستخدم قالبًا بسيطًا لتفكيك فكرة غامضة إلى سيناريو ومحفز وعقبة ومعيار نجاح</li><li>كيفية استخدام JTBD في منتجات AI وأسئلة المقابلة وتنظيم التعليمات</li></ol><p><a id="jtbd-what"></a></p><h2 id="_1-ما-هو-jobs-to-be-done" tabindex="-1"><a href="#top-jtbd">1. ما هو Jobs to Be Done</a> <a class="header-anchor" href="#_1-ما-هو-jobs-to-be-done" aria-label="Permalink to “1. ما هو Jobs to Be Done”">​</a></h2><p>يُختصر Jobs to Be Done غالبًا بـ <strong>JTBD</strong>. الفكرة الأساسية وراءه مرتبطة بالتعبير الكلاسيكي الذي روجته فرقة Clayton Christensen: <strong>المستخدمون سيوظفون منتجًا معينًا لإنجاز مهمة.</strong></p><p>&quot;المهمة&quot; هنا ليست إجراءً سطحيًا في قائمة المهام، بل نوع من <strong>التقدم</strong> يأمل المستخدم أن يحدث في حالته. مثلاً:</p><ul><li>ليس &quot;أريد أداة AI لمحاضر الاجتماعات&quot;، بل &quot;أريد خلال 10 دقائق بعد الاجتماع ترتيب النقاط الرئيسية والمهام والمسؤولين بوضوح، بدلاً من الاعتماد على الذاكرة لاستكمال الملاحظات&quot;</li><li>ليس &quot;أريد تطبيقًا لتتبع المصاريف&quot;، بل &quot;أريد أن أعرف أين يذهب مالي حقًا، حتى لا أشعر بالقلق في نهاية الشهر&quot;</li><li>ليس &quot;أريد مُحسّنًا للسيرة الذاتية&quot;، بل &quot;أريد تقديم سيرة ذاتية لائقة بثقة أكبر، ولا أريد الشك في كل مرة أقدم فيها أن كتابتي سيئة للغاية&quot;</li></ul><p>لذا، <strong>JTBD لا يركز على شكل المنتج، بل على سبب احتياج المستخدم له في هذه اللحظة.</strong></p><p>هذا هو السبب أيضًا في أن العديد من المنتجات التي تبدو مختلفة تتنافس في الواقع على نفس الوظيفة. المستخدم يريد &quot;ألا يكون الطريق إلى العمل مملًا&quot;، والأشياء القابلة للتسكين قد تكون فيديوهات قصيرة أو بودكاست أو ألعاب أو دردشة أو حتى الغفوة. المستخدم يريد &quot;فهم ملف PDF طويل بسرعة&quot;، والأشياء القابلة للتسكين قد تكون أداة تلخيص AI أو متدرب أو زميل أو القراءة بصعوبة بنفسه أو عدم القراءة أبدًا.</p><p>بمجرد أن تنظر إلى المشكلة بهذه الزاوية، ستكتشف أن منافسك الحقيقي غالبًا ليس &quot;تطبيقًا آخر يشبهك&quot;، بل <strong>جميع البدائل المقبولة للمستخدم حاليًا</strong>.</p><h2 id="_2-ما-الفرق-بين-jtbd-وصورة-المستخدم-وقائمة-الوظائف" tabindex="-1">2. ما الفرق بين JTBD وصورة المستخدم وقائمة الوظائف <a class="header-anchor" href="#_2-ما-الفرق-بين-jtbd-وصورة-المستخدم-وقائمة-الوظائف" aria-label="Permalink to “2. ما الفرق بين JTBD وصورة المستخدم وقائمة الوظائف”">​</a></h2><p>العديد من المبتدئين عند بداية تحليل المتطلبات، يكتبون أولاً صورة المستخدم: 25 سنة، أنثى، مدينة من الدرجة الأولى، موظفة مكتبية، تحب أدوات الكفاءة، مستعدة لتجربة منتجات جديدة. هذه المعلومات لا يمكن القول إنها غير مفيدة تمامًا، لكنها عادةً <strong>لا تكفي لتفسير سبب اتخاذ الشخص إجراءً في هذه اللحظة.</strong></p><p>JTBD يهتم أكثر بالأسئلة التالية:</p><ul><li>في أي سيناريو قرر البحث عن حل</li><li>ما الذي تعثر فيه بالضبط في ذلك الوقت</li><li>ما الشيء الذي يريد دفعه إلى الخطوة التالية</li><li>بأي طريقة غير فعالة يتدبر الأمر حاليًا</li><li>إذا تم حل الأمر جيدًا، أي نتيجة ستجعله يشعر أن &quot;الأمر يستحق&quot;</li></ul><p>بعبارة أخرى، <strong>صورة المستخدم أشبه بـ &quot;من هذا الشخص تقريبًا&quot;، بينما JTBD أشبه بـ &quot;ما الذي يريد هذا الشخص إنجازه بالضبط الآن&quot;.</strong></p><p>وبالمثل، قائمة الوظائف أيضًا تضلل الناس بسهولة. المستخدم يقول &quot;أريد التصدير إلى Word&quot; و&quot;أريد إعادة كتابة AI&quot; و&quot;أريد الإدخال الصوتي&quot;، كلها تعبيرات سطحية. JTBD سيستمر في السؤال:</p><ul><li>لماذا تحتاج إلى التصدير إلى Word الآن، وليس PDF؟</li><li>تريد إعادة الكتابة، هل لأن الأسلوب سيء، أم لأنك تحتاج إلى التكيف مع جماهير مختلفة؟</li><li>تريد الإدخال الصوتي، هل لأنك كسول عن الكتابة، أم لأنك غالبًا ما تمشي أو تقود أو تسجل فورًا بعد الاجتماع؟</li></ul><p>في كثير من الأحيان، <strong>الوظيفة هي مجرد ترجمة مؤقتة للوظيفة</strong>. إذا جمعت الوظائف فقط، فمن السهل أن تصنع منتجًا &quot;يضيف كل ما يقوله المستخدم&quot;؛ لكن إذا استطعت رؤية الوظيفة وراء الوظائف، ستكون لديك فرصة أكبر لصنع حل سلس حقًا وتنافسي حقًا.</p><h2 id="_3-مثال-يمكن-حتى-للمبتدئين-فهمه" tabindex="-1">3. مثال يمكن حتى للمبتدئين فهمه <a class="header-anchor" href="#_3-مثال-يمكن-حتى-للمبتدئين-فهمه" aria-label="Permalink to “3. مثال يمكن حتى للمبتدئين فهمه”">​</a></h2><p>لا تستعجل في التفكير في منتجات AI معقدة، لنبدأ بمثال من الحياة.</p><p>لنفترض أن شخصًا لا يلحق بتناول الفطور قبل الخروج في الصباح، فيشتري غالبًا شطيرة وقهوة عند مدخل المترو. ظاهريًا، هو &quot;يشتري&quot; الفطور؛ لكن بالنظر إليه من منظور JTBD، ما يريد إنجازه حقًا قد يكون:</p><ul><li>في صباحات متسرعة، حل وجبة بأقل جهد ذهني</li><li>ألا يجوع بشكل فظيع قبل الوصول إلى الشركة</li><li>ألا يعطل إيقاع التنقل بسبب تناول الفطور</li></ul><p>في هذه اللحظة، ما يوظفه المستخدم ليس &quot;شطيرة من علامة تجارية ثابتة&quot;، بل حل يمكنه دفع صباحه بسلاسة. إذا كان المتجر المجاور أسرع وأقرب وأكثر استقرارًا، فقد يستبدل خياره فورًا.</p><p>نقل هذا المنطق إلى منتجات AI يكون أكثر وضوحًا.</p><p>مثلاً، إذا كنت تريد صنع &quot;أداة AI لمحاضر الاجتماعات&quot;. إذا توقفت عند مستوى الوظائف فقط، فمن السهل أن تبدأ في التفكير:</p><ul><li>هل يتم دعم رفع الصوت</li><li>هل يتم توصيل فصل المتحدثين</li><li>هل يتم التصدير إلى Markdown</li><li>هل يتم توليد المهام تلقائيًا</li></ul><p>كل هذا صحيح، لكنه غير كافٍ. مع JTBD اسأل طبقة أخرى، ما يريد المستخدم إنجازه حقًا قد يكون:</p><ul><li>أريد خلال 10 دقائق بعد الاجتماع، مشاركة نتائج المناقشة مع من لم يحضر</li><li>أريد استخراج المهام والمسؤولين والمواعيد النهائية بوضوح، بدلاً من جعل الفريق يتعاون بالذاكرة</li><li>أريد تقليل وقت تنظيم محتوى الاجتماع المتكرر، وتوفير الجهد للقرارات والتقدم</li></ul><p>بمجرد توضيح الوظيفة، ستطفو أولويات العديد من الوظائف تلقائيًا. الأهم في النسخة الأولى ربما ليس &quot;دعم 12 تنسيق تصدير&quot;، بل:</p><ul><li>هيكل المحضر يجب أن يكون واضحًا بما فيه الكفاية</li><li>استخراج المهام يجب أن يكون مستقرًا</li><li>مشاركة الرابط يجب أن تكون مريحة</li><li>نتيجة الإخراج يجب أن تجعل المستخدم يجرؤ على إعادة توجيهها للفريق مباشرة</li></ul><p>هذه هي قيمة JTBD: <strong>يساعدك على العودة من &quot;ما القدرات التي سأجمعها&quot; إلى &quot;ما التقدم الذي سأساعد المستخدم على تحقيقه&quot;.</strong></p><h2 id="_4-قالب-jtbd-عملي" tabindex="-1">4. قالب JTBD عملي <a class="header-anchor" href="#_4-قالب-jtbd-عملي" aria-label="Permalink to “4. قالب JTBD عملي”">​</a></h2><p>إذا كنت مبتدئًا، يمكنك ألا تحاول جعل JTBD أكاديميًا جدًا. أمسك أولاً بأهم 5 عناصر عملية فقط.</p><h3 id="_4-1-السيناريو" tabindex="-1">4.1 السيناريو <a class="header-anchor" href="#_4-1-السيناريو" aria-label="Permalink to “4.1 السيناريو”">​</a></h3><p>في أي لحظة وأي بيئة يتذكر المستخدم هذا المنتج؟</p><ul><li>بعد الاجتماع</li><li>عندما يطلب المدير مواد بشكل مفاجئ</li><li>في المساء عند الاستعداد لتقديم السيرة الذاتية</li><li>في نهاية الشهر عندما يكتشف أن المال لا يكفي مرة أخرى</li></ul><p><strong>الاحتياجات بدون سيناريو عادةً ليست حقيقية بعد.</strong></p><h3 id="_4-2-المحفز" tabindex="-1">4.2 المحفز <a class="header-anchor" href="#_4-2-المحفز" aria-label="Permalink to “4.2 المحفز”">​</a></h3><p>ما الذي جعله يقرر البحث عن حل فورًا؟</p><ul><li>أن يثقل عليه مستند طويل ولا يعرف من أين يبدأ القراءة</li><li>غدًا يجب تسليم المواد، واليوم يكتشف أن التنسيق فوضوي</li><li>للتو سأله المدير عن التقدم، ويدرك أنه لم ينظم بوضوح</li><li>يريد الاستمرار في التسجيل، لكن الكتابة اليدوية والنسخ والتنظيم كلها مزعجة جدًا</li></ul><p>نقطة التحفيز غالبًا ما تحمل مشاعر. هذه المشاعر مهمة، لأنها تحدد سبب اتخاذ المستخدم إجراءً في هذه اللحظة.</p><h3 id="_4-3-التقدم-المطلوب-إنجازه" tabindex="-1">4.3 التقدم المطلوب إنجازه <a class="header-anchor" href="#_4-3-التقدم-المطلوب-إنجازه" aria-label="Permalink to “4.3 التقدم المطلوب إنجازه”">​</a></h3><p>لا يريد فقط &quot;القيام بإجراء&quot;، بل يريد دفع نفسه إلى أي حالة جديدة؟</p><ul><li>من الفوضى إلى الوضوح</li><li>من القلق إلى الطمأنينة</li><li>من التأجيل إلى البدء</li><li>من انخفاض الكفاءة إلى السلاسة</li><li>من عدم القدرة على الشرح إلى القدرة على التسليم المباشر</li></ul><p>في هذه الخطوة، كلمة &quot;التقدم&quot; مهمة جدًا. لأن الكثير من الناس لا يشترون الأدوات حقًا، بل يشترون <strong>تغير الحالة</strong>.</p><h3 id="_4-4-البديل-الحالي" tabindex="-1">4.4 البديل الحالي <a class="header-anchor" href="#_4-4-البديل-الحالي" aria-label="Permalink to “4.4 البديل الحالي”">​</a></h3><p>بدون منتجك، كيف يفعل ذلك؟</p><ul><li>نسخ ولصق يدويًا</li><li>استخدام Excel أو الملاحظات للتدبير</li><li>طلب المساعدة من زميل</li><li>التأجيل وعدم الفعل</li><li>التبديل بين عدة أدوات</li></ul><p>من هو البديل، هو بيئتك التنافسية الحقيقية.</p><h3 id="_4-5-معيار-النجاح" tabindex="-1">4.5 معيار النجاح <a class="header-anchor" href="#_4-5-معيار-النجاح" aria-label="Permalink to “4.5 معيار النجاح”">​</a></h3><p>كيف يُعرف أن الأمر قد حُل حقًا؟</p><ul><li>الحصول على نتيجة قابلة للمشاركة خلال 10 دقائق</li><li>عدم الحاجة إلى تعديل كبير قبل الإرسال للآخرين</li><li>عدم نسيان العناصر أو الأخطاء أو المهام بسهولة</li><li>معرفة الخطوة التالية من أول استخدام</li></ul><p>إذا لم تستطع حتى توضيح &quot;كيف يحكم المستخدم على ما إذا كان الأمر يستحق&quot;، فهذا الاتجاه على الأرجح لم يتم تضييقه جيدًا بعد.</p><p><a id="jtbd-formula"></a></p><h2 id="_5-صيغة-الجملة-الواحدة-التي-يمكن-استخدامها-مباشرة" tabindex="-1"><a href="#top-jtbd">5. صيغة الجملة الواحدة التي يمكن استخدامها مباشرة</a> <a class="header-anchor" href="#_5-صيغة-الجملة-الواحدة-التي-يمكن-استخدامها-مباشرة" aria-label="Permalink to “5. صيغة الجملة الواحدة التي يمكن استخدامها مباشرة”">​</a></h2><p>عندما تريد ترتيب اتجاه منتج، يمكنك استخدام هذه الصيغة العملية جدًا:</p><blockquote><p>عندما __________، أريد __________، لكي أتمكن من __________.<br> حاليًا لا يمكنني سوى __________ لإنجاز هذا الأمر بالكاد.</p></blockquote><p>مثلاً:</p><blockquote><p>عندما أنتهي من اجتماع مشروع مليء بالمعلومات، أريد الحصول بسرعة على محضر يتضمن المهام والمسؤولين والمواعيد النهائية، لكي أتمكن من مزامنة الفريق فورًا ودفع التنفيذ.<br> حاليًا لا يمكنني سوى الاعتماد على ذاكرتي وتصفح سجل الدردشة والتنظيم اليدوي لإنجاز هذا الأمر بالكاد.</p></blockquote><p>مثال آخر:</p><blockquote><p>عندما أستعد لتقديم وظيفة جديدة، أريد تحويل خبراتي السابقة بسرعة إلى نسخة تتناسب أكثر مع الوظيفة، لكي أتمكن من تقديم سيرة ذاتية لائقة بثقة أكبر.<br> حاليًا لا يمكنني سوى نسخ سيرتي القديمة مرارًا وتعديل الصياغة يدويًا، حتى أصبح أقل ثقة مع كل تعديل.</p></blockquote><p>إذا استطعت كتابة جملة واحدة بهذه الدرجة من الوضوح، فتصميم الصفحات وتصميم التعليمات والحكم على أولويات الوظائف سيصبح أسهل بكثير.</p><h2 id="_6-عند-صنع-منتجات-ai،-ثلاث-طبقات-من-الوظائف-التي-يجب-مراعاتها-بشكل-خاص" tabindex="-1">6. عند صنع منتجات AI، ثلاث طبقات من الوظائف التي يجب مراعاتها بشكل خاص <a class="header-anchor" href="#_6-عند-صنع-منتجات-ai،-ثلاث-طبقات-من-الوظائف-التي-يجب-مراعاتها-بشكل-خاص" aria-label="Permalink to “6. عند صنع منتجات AI، ثلاث طبقات من الوظائف التي يجب مراعاتها بشكل خاص”">​</a></h2><p>العديد من منتجات AI تبدو قوية جدًا في العرض التوضيحي للوظائف، لكنها لا تحافظ على المستخدمين بعد الإطلاق الفعلي، والسبب الشائع هو أنها حلت الإجراء السطحي فقط ولم تحل الوظيفة الأعمق.</p><p>يمكنك تقسيم الوظيفة تقريبًا إلى ثلاث طبقات:</p><h3 id="_6-1-طبقة-الوظائف" tabindex="-1">6.1 طبقة الوظائف <a class="header-anchor" href="#_6-1-طبقة-الوظائف" aria-label="Permalink to “6.1 طبقة الوظائف”">​</a></h3><p>ما هي المهمة السطحية؟</p><ul><li>تلخيص المستندات</li><li>إعادة كتابة النصوص</li><li>استخراج المهام</li><li>توليد الصور</li></ul><p>هذه هي الطبقة الأسهل للمستخدم في التعبير عنها شفهيًا.</p><h3 id="_6-2-الطبقة-العاطفية" tabindex="-1">6.2 الطبقة العاطفية <a class="header-anchor" href="#_6-2-الطبقة-العاطفية" aria-label="Permalink to “6.2 الطبقة العاطفية”">​</a></h3><p>ما الذي يريد المستخدم تقليله من عدم الراحة، أو ما الشعور الذي يريد الحصول عليه؟</p><ul><li>لا يريد أن يذعر هكذا</li><li>لا يريد أن يبدو غير محترف</li><li>لا يريد البدء من الصفر في كل مرة</li><li>يريد شعورًا أكبر بالسيطرة</li></ul><p>العديد من نوايا الدفع مرتبطة ارتباطًا وثيقًا بالطبقة العاطفية في الواقع.</p><h3 id="_6-3-الطبقة-الاجتماعية" tabindex="-1">6.3 الطبقة الاجتماعية <a class="header-anchor" href="#_6-3-الطبقة-الاجتماعية" aria-label="Permalink to “6.3 الطبقة الاجتماعية”">​</a></h3><p>ما الذي يريد المستخدم أن يصبح عليه في نظر الآخرين؟</p><ul><li>أن يبدو أكثر موثوقية</li><li>أن يكون أكثر تنظيمًا في الفريق</li><li>أن يكون أكثر احترافية أمام العملاء</li><li>أن يكون أكثر قدرة على التعبير على منصات التواصل الاجتماعي</li></ul><p>إذا صنعت الطبقة الوظيفية فقط، فمن السهل استبدال منتجك؛ لكن إذا فهمت الطبقة العاطفية والاجتماعية في نفس الوقت، فستجد قيمة لزجة حقيقية بسهولة أكبر.</p><h2 id="_7-استخدام-jtbd-بشكل-عكسي-لفرز-اتجاهات-المنتج" tabindex="-1">7. استخدام JTBD بشكل عكسي لفرز اتجاهات المنتج <a class="header-anchor" href="#_7-استخدام-jtbd-بشكل-عكسي-لفرز-اتجاهات-المنتج" aria-label="Permalink to “7. استخدام JTBD بشكل عكسي لفرز اتجاهات المنتج”">​</a></h2><p>أحيانًا ليس لديك منتج بالفعل، بل لديك 3 إلى 5 أفكار ولا تعرف أيها تصنع. JTBD مناسب جدًا هنا للفرز.</p><p>يمكنك أخذ كل فكرة وسؤال نفسك 5 أسئلة:</p><ol><li>هل السيناريو المقابل لهذه الفكرة محدد بما فيه الكفاية؟</li><li>هل يستخدم المستخدم بالفعل طريقة غير فعالة لحل المشكلة الآن؟</li><li>هل ألم هذه الوظيفة قوي بما فيه الكفاية، أو متكرر بما فيه الكفاية؟</li><li>إذا صنعتها جيدًا، هل سيشعر المستخدم بوضوح بـ &quot;تحسنت حالتي&quot;؟</li><li>هل يمكن في النسخة الأولى التركيز فقط على الخطوة الرئيسية لهذه الوظيفة، وصنع نسخة صغيرة لكنها مفيدة؟</li></ol><p>إذا كان اتجاه ما في النهاية لا يزال يمكنك قول &quot;يبدو مثيرًا للاهتمام&quot; فقط، لكن لا يمكنك توضيح المحفز والبديل ومعيار النجاح، فهو على الأرجح مجرد إلهام غامض، وليس اتجاهًا ناضجًا.</p><h2 id="_8-أسئلة-يمكن-استخدامها-مباشرة-في-مقابلات-المستخدمين" tabindex="-1">8. أسئلة يمكن استخدامها مباشرة في مقابلات المستخدمين <a class="header-anchor" href="#_8-أسئلة-يمكن-استخدامها-مباشرة-في-مقابلات-المستخدمين" aria-label="Permalink to “8. أسئلة يمكن استخدامها مباشرة في مقابلات المستخدمين”">​</a></h2><p>العديد من الأشخاص عند القيام بالبحث يسألون: &quot;ما الوظائف التي تريدها؟&quot; هذا النوع من الأسئلة يحصل بسهولة على إجابات سطحية.</p><p>JTBD أنسب لطرح الأسئلة التالية:</p><ul><li>متى واجهت هذه المشكلة آخر مرة؟</li><li>ماذا كنت تفعل في ذلك الوقت، ولماذا تعثرت؟</li><li>كيف حللتها في النهاية؟</li><li>في هذه العملية، أين كان أكثر ما يزعجك وأبطأك وأقل ما يطمئنك؟</li><li>إذا كانت هناك أداة يمكنها مساعدتك، أي نتيجة ستجعلك تشعر أنها مفيدة حقًا؟</li><li>ما البدائل التي جربتها؟ ولماذا لم تكن جيدة بما فيه الكفاية؟</li></ul><p>هذا النوع من الأسئلة يعيد الحوار إلى التجارب الحقيقية بدلاً من البقاء في التفضيلات المتخيلة.</p><h2 id="_9-استخدام-ai-لمساعدتك-في-تفكيك-jtbd" tabindex="-1">9. استخدام AI لمساعدتك في تفكيك JTBD <a class="header-anchor" href="#_9-استخدام-ai-لمساعدتك-في-تفكيك-jtbd" aria-label="Permalink to “9. استخدام AI لمساعدتك في تفكيك JTBD”">​</a></h2><p>JTBD نفسه ليس اختراع AI، لكن AI مناسب جدًا لمساعدتك في تنظيم وتلخيص JTBD.</p><p>مثلاً، إذا جمعت 5 إلى 10 تعليقات من المستخدمين، يمكنك إرسالها للنموذج وجعله يلخص وفقًا للهيكل التالي:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>العب دور مساعد بحث المنتج.</span></span>
<span class="line"><span>سأعطيك بعض الكلمات الأصلية للمستخدم، لا تعط اقتراحات وظيفية أولاً،</span></span>
<span class="line"><span>بل نظم أولاً وفقًا لإطار Jobs to Be Done:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. في أي سيناريو يوجد المستخدم</span></span>
<span class="line"><span>2. ما هو الحدث الذي حفزه على اتخاذ إجراء</span></span>
<span class="line"><span>3. ما هو التقدم الذي يريد إنجازه حقًا</span></span>
<span class="line"><span>4. ما هو البديل الحالي</span></span>
<span class="line"><span>5. ما هو معيار النجاح الأكثر أهمية لديه</span></span>
<span class="line"><span>6. ما هي الكلمات العاطفية المتكررة في هذه التعليقات</span></span>
<span class="line"><span></span></span>
<span class="line"><span>أخيرًا، نظم هذه المحتويات في 3 فرضيات JTBD الأكثر استحقاقًا للتحقق أولاً.</span></span></code></pre></div><p>إذا كان لديك فكرة بالفعل، يمكنك أيضًا جعل AI يساعدك في الجولة الأولى من التضييق:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>أريد صنع [فكرتك للمنتج].</span></span>
<span class="line"><span>لا تعطني قائمة وظائف مباشرة، بل استخدم طريقة Jobs to Be Done لمساعدتي في التحليل:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. أي سيناريوهات محددة قد يخدمها هذا المنتج</span></span>
<span class="line"><span>2. ما هي الوظيفة الأساسية التي يريد المستخدم إنجازها في كل سيناريو</span></span>
<span class="line"><span>3. ما هي البدائل الحالية</span></span>
<span class="line"><span>4. أي وظيفة هي الأنسب كبداية لـ MVP ولماذا</span></span>
<span class="line"><span>5. اكتب الوظيفة الموصى بها نهائيًا كجملة JTBD واضحة</span></span></code></pre></div><h2 id="_10-4-أخطاء-شائعة-للمبتدئين" tabindex="-1">10. 4 أخطاء شائعة للمبتدئين <a class="header-anchor" href="#_10-4-أخطاء-شائعة-للمبتدئين" aria-label="Permalink to “10. 4 أخطاء شائعة للمبتدئين”">​</a></h2><h3 id="_10-1-كتابة-الوظيفة-كاسم-وظيفة" tabindex="-1">10.1 كتابة الوظيفة كاسم وظيفة <a class="header-anchor" href="#_10-1-كتابة-الوظيفة-كاسم-وظيفة" aria-label="Permalink to “10.1 كتابة الوظيفة كاسم وظيفة”">​</a></h3><p>&quot;تلخيص AI&quot; و&quot;تصنيف ذكي&quot; و&quot;توليد تلقائي&quot; ليست وظائف، بل هي طرق تنفيذ محتملة فقط.</p><h3 id="_10-2-كتابة-المجموعة-المستهدفة-بشكل-واسع-جدًا" tabindex="-1">10.2 كتابة المجموعة المستهدفة بشكل واسع جدًا <a class="header-anchor" href="#_10-2-كتابة-المجموعة-المستهدفة-بشكل-واسع-جدًا" aria-label="Permalink to “10.2 كتابة المجموعة المستهدفة بشكل واسع جدًا”">​</a></h3><p>&quot;جميع العاملين&quot; و&quot;جميع الطلاب&quot; و&quot;جميع رواد الأعمال&quot; عادةً ما تكون واسعة جدًا. كلما كانت أوسع، صعب عليك رؤية السيناريوهات الحقيقية.</p><h3 id="_10-3-الاستماع-فقط-لما-يقوله-المستخدم،-دون-النظر-إلى-ما-يفعله" tabindex="-1">10.3 الاستماع فقط لما يقوله المستخدم، دون النظر إلى ما يفعله <a class="header-anchor" href="#_10-3-الاستماع-فقط-لما-يقوله-المستخدم،-دون-النظر-إلى-ما-يفعله" aria-label="Permalink to “10.3 الاستماع فقط لما يقوله المستخدم، دون النظر إلى ما يفعله”">​</a></h3><p>المستخدم سيصف ما يريده، لكن أولوياته الحقيقية غالبًا ما تكون مخفية في كيفية تدبيره للمشكلة حاليًا.</p><h3 id="_10-4-الرغبة-في-صنع-منصة-شاملة-من-البداية" tabindex="-1">10.4 الرغبة في صنع منصة شاملة من البداية <a class="header-anchor" href="#_10-4-الرغبة-في-صنع-منصة-شاملة-من-البداية" aria-label="Permalink to “10.4 الرغبة في صنع منصة شاملة من البداية”">​</a></h3><p>الطريقة الصحيحة لاستخدام JTBD عادةً ليست &quot;سأصنع منصة كبيرة تفعل كل شيء&quot;، بل التركيز أولاً على خطوة رئيسية واحدة في سيناريو واحد، وصنعها مريحة جدًا.</p><h2 id="_11-ملخص" tabindex="-1">11. ملخص <a class="header-anchor" href="#_11-ملخص" aria-label="Permalink to “11. ملخص”">​</a></h2><p>أكثر جانب قيم في Jobs to Be Done ليس إعطائك مصطلحًا جديدًا، بل مساعدتك في تغيير زاوية المراقبة: <strong>لا تركز فقط على وظائف المنتج، بل ركز على ما يريد المستخدم دفذه إلى الخطوة التالية.</strong></p><p>عندما تبدأ في سؤال نفسك مرارًا:</p><ul><li>في أي سيناريو يوظف المستخدم هذا المنتج</li><li>أين تعثر بالضبط</li><li>بأي طريقة يتدبر الأمر حاليًا</li><li>بعد حل المشكلة، ماذا ستتغير حالته</li></ul><p>ستكتشف أن العديد من الأفكار الغامضة أصبحت واضحة فجأة، وأن العديد من الوظائف الفخمة لم تعد مهمة جدًا فجأة أيضًا.</p><p>صنع المنتجات، خاصة منتجات AI، أكثر ما يخافه هو الانغماس في عرض القدرات منذ البداية. JTBD يمكنه سحب انتباهك إلى المكان المهم حقًا: <strong>لماذا يحتاجك المستخدم، وما التقدم الذي تساعده في إنجازه بالضبط.</strong></p><p><a id="jtbd-ai"></a></p><h2 id="_12-كيفية-استخدام-ai-لمساعدتك-في-تطبيق-jtbd" tabindex="-1"><a href="#top-jtbd">12. كيفية استخدام AI لمساعدتك في تطبيق JTBD</a> <a class="header-anchor" href="#_12-كيفية-استخدام-ai-لمساعدتك-في-تطبيق-jtbd" aria-label="Permalink to “12. كيفية استخدام AI لمساعدتك في تطبيق JTBD”">​</a></h2><p>JTBD ليس اختراع AI، لكن AI مناسب جدًا ليكون مساعدك البحثي ومساعد التنظيم ومساعد المقارنة في هذا الإطار. المفتاح هو: <strong>دع AI يساعدك في التنظيم والتوسيع، بدلاً من التخمين بدلاً منك عن المستخدم.</strong></p><p>يمكنك استخدامه هكذا:</p><h3 id="_12-1-دع-ai-يساعدك-في-إعادة-كتابة-الفكرة-الغامضة-كفرضية-jtbd" tabindex="-1">12.1 دع AI يساعدك في إعادة كتابة الفكرة الغامضة كفرضية JTBD <a class="header-anchor" href="#_12-1-دع-ai-يساعدك-في-إعادة-كتابة-الفكرة-الغامضة-كفرضية-jtbd" aria-label="Permalink to “12.1 دع AI يساعدك في إعادة كتابة الفكرة الغامضة كفرضية JTBD”">​</a></h3><p>عندما يكون لديك فقط وصف غامض في ذهنك، مثل &quot;أريد صنع أداة تساعد طلاب الجامعات في إيجاد تدريب&quot;، يمكنك جعل AI يساعدك أولاً في تفكيكها إلى عدة وظائف محتملة:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>لدي فكرة منتج غامضة الآن: [فكرتك]</span></span>
<span class="line"><span>لا تعطني قائمة وظائف مباشرة، بل استخدم طريقة Jobs to Be Done لمساعدتي في التحليل:</span></span>
<span class="line"><span>1. أي سيناريوهات محددة قد تقابلها</span></span>
<span class="line"><span>2. ما هو التقدم الذي يريد المستخدم إنجازه حقًا في كل سيناريو</span></span>
<span class="line"><span>3. ما هي البدائل الحالية المحتملة</span></span>
<span class="line"><span>4. أي وظيفة أنسب لصنع MVP أولاً</span></span>
<span class="line"><span>أخيرًا اكتب كل وظيفة كجملة JTBD واضحة.</span></span></code></pre></div><p>يمكنك حتى أن تكتب الإدخال ببساطة شديدة:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>أريد صنع شيء يساعد طلاب الجامعات في إيجاد تدريب.</span></span>
<span class="line"><span>أنا الآن لا أستطيع أن أشرح بالضبط ماذا سأصنع، ساعدني في التفكير ماذا يريد المستخدم إنجازه حقًا.</span></span></code></pre></div><p>AI قد يعطي مخرجات مفيدة مثل هذه:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>اتجاهات JTBD المحتملة:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. عندما أستعد لأول مرة لتقديم طلب تدريب، أريد أن أعرف بسرعة ما المواد التي يجب أن أعد أولاً،</span></span>
<span class="line"><span>لكي لا أتأخر في التقديم بسبب الفوضى في المعلومات.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. عندما أرى وظيفة تدريب، أريد أن أحكم بسرعة على ما إذا كانت تست التقديم،</span></span>
<span class="line"><span>لكي لا أضيع وقتًا كثيرًا على وظائف غير مناسبة.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. عندما أبدأ التقديم، أريد تحويل سيرتي الذاتية الحالية إلى نسخة تتناسب أكثر مع الوظيفة،</span></span>
<span class="line"><span>لكي أتمكن من إكمال التقديم بسرعة أكبر ورفع معدل القبول.</span></span></code></pre></div><p>قيمة هذا النوع من المخرجات هي أنه سيأخذ فكرتك الواسعة جدًا ويقسمها إلى عدة اتجاهات أقرب إلى السيناريوهات الحقيقية.</p><h3 id="_12-2-دع-ai-يساعدك-في-تنظيم-الكلمات-الأصلية-من-المقابلات" tabindex="-1">12.2 دع AI يساعدك في تنظيم الكلمات الأصلية من المقابلات <a class="header-anchor" href="#_12-2-دع-ai-يساعدك-في-تنظيم-الكلمات-الأصلية-من-المقابلات" aria-label="Permalink to “12.2 دع AI يساعدك في تنظيم الكلمات الأصلية من المقابلات”">​</a></h3><p>إذا قمت بالفعل ببعض مقابلات المستخدمين، يمكنك تسليم سجلات المقابلات إلى AI وجعله يساعدك في استخلاص السيناريوهات المتكررة ونقاط التحفيز والبدائل ومعايير النجاح.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>فيما يلي الكلمات الأصلية من 5 مستخدمين.</span></span>
<span class="line"><span>لا تعط حلولاً أولاً، بل نظم وفقًا لإطار JTBD:</span></span>
<span class="line"><span>1. في أي سيناريو يوجد المستخدم</span></span>
<span class="line"><span>2. ما هو الحدث الذي حفزه على اتخاذ إجراء</span></span>
<span class="line"><span>3. ما هو التقدم الذي يريد إنجازه حقًا</span></span>
<span class="line"><span>4. ما هو البديل الحالي</span></span>
<span class="line"><span>5. ما هو معيار النجاح الأكثر أهمية لديه</span></span>
<span class="line"><span>6. أي المعلومات تتكرر عبر عدة مستخدمين</span></span>
<span class="line"><span>أخيرًا نظم في 3 فرضيات JTBD الأكثر استحقاقًا للتحقق أولاً.</span></span></code></pre></div><p>يمكنك أيضًا كتابة إدخال بسيط جدًا هكذا:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>سألت 3 أشخاص، قالوا تقريبًا هكذا:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. في كل مرة أريد تقديم تدريب يجب أن أعدل سيرتي الذاتية من جديد، هذا مزعج جدًا.</span></span>
<span class="line"><span>2. أكثر ما أخافه حقًا هو أنني لا أعرف ما إذا كانت كتابتي صحيحة.</span></span>
<span class="line"><span>3. أنا الآن أطلب من الطلاب الأكبر سناً مساعدتي في المراجعة، لكن من المحرج أن أزعجهم في كل مرة.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ساعدني في التنظيم، ماذا يريدون إنجازه حقًا.</span></span></code></pre></div><p>AI قد يخرج:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>نتيجة التنظيم:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- السيناريو المشترك: قبل تقديم طلب تدريب، يجب التعامل مع السيرة الذاتية</span></span>
<span class="line"><span>- الصعوبة المشتركة: لا أعرف كيف أعدل إلى مستوى &quot;جيد بما فيه الكفاية&quot;</span></span>
<span class="line"><span>- البديل الحالي: طلب مساعدة الطلاب الأكبر سناً في المراجعة، التعديل المتكرر بنفسه</span></span>
<span class="line"><span>- JTBD المحتمل:</span></span>
<span class="line"><span>  عندما أستعد لتقديم تدريب، أريد أن أحكم بسرعة على ما إذا كانت سيرتي الذاتية قد وصلت إلى مستوى قابل للتقديم،</span></span>
<span class="line"><span>  لكي لا أبقى عالقًا في &quot;سأعدل مرة أخرى&quot; ولا أستطيع التقديم.</span></span></code></pre></div><p>هذا النوع من المخرجات مفيد جدًا، لأنه يساعدك على استخلاص شيء أشبه بـ &quot;الاحتياج&quot; من الكلمات المتفرقة.</p><h3 id="_12-3-دع-ai-يقوم-بجولة-خفيفة-من-البحث-عبر-الإنترنت" tabindex="-1">12.3 دع AI يقوم بجولة خفيفة من البحث عبر الإنترنت <a class="header-anchor" href="#_12-3-دع-ai-يقوم-بجولة-خفيفة-من-البحث-عبر-الإنترنت" aria-label="Permalink to “12.3 دع AI يقوم بجولة خفيفة من البحث عبر الإنترنت”">​</a></h3><p>قبل أن تبدأ المقابلات واسعة النطاق، يمكنك جعل AI يساعدك في بعض المسح الخفيف للمعلومات الخارجية:</p><ul><li>في المنتديات العامة أو المجتمعات، كيف يشكو الناس من هذه المشكلة</li><li>أي طبقة من المشكلة تحلها المنتجات الموجودة أساسًا</li><li>ما هي البدائل الأكثر شيوعًا لدى المستخدمين</li><li>في التقييمات الشائعة، ما أكثر ما يرضي الناس وما أقل ما يرضيهم</li></ul><p>هذا النوع من البحث لا يمكنه استبدال مقابلات المستخدمين الحقيقية، لكنه مناسب جدًا كإحماء لمرحلة Discover، لمساعدتك في بناء خريطة المشاكل أولاً.</p><p>إدخال بسيط يمكن أن يكون:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ساعدني في البحث:</span></span>
<span class="line"><span>&quot;ما هي نقاط الألم الأكثر شيوعًا عند تعديل السيرة الذاتية وتقديم طلبات التدريب لطلاب الجامعات؟&quot;</span></span>
<span class="line"><span>ركز على ما يقوله الناس بأنفسهم في المنتديات العامة ومنشورات الخبرة ومجتمعات التوظيف.</span></span>
<span class="line"><span>ساعدني في تنظيم 5 مشاكل الأكثر شيوعًا.</span></span></code></pre></div><p>AI قد يخرج:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>تنظيم نقاط الألم الشائعة:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. لا أعرف ماذا أكتب في السيرة الذاتية، الخبرات قليلة جدًا</span></span>
<span class="line"><span>2. لا أعرف كيف أعدل لتناسب وظائف مختلفة</span></span>
<span class="line"><span>3. عدلت عدة نسخ، لكنني لا أزال غير متأكد مما إذا كانت جيدة بما فيه الكفاية</span></span>
<span class="line"><span>4. لا أجد شخصًا موثوقًا لمساعدتي في المراجعة</span></span>
<span class="line"><span>5. عملية التقديم معقدة، من السهل التأجيل</span></span></code></pre></div><p>هذا النوع من المخرجات لا يمكن اعتباره استنتاجًا نهائيًا، لكنه مناسب جدًا لمساعدتك في تحديد أي نوع من المشاكل يجب أن تعطي الأولوية للمقابلات عنه.</p><h3 id="_12-4-دع-ai-يلعب-دور-الجانب-المعارض" tabindex="-1">12.4 دع AI يلعب دور &quot;الجانب المعارض&quot; <a class="header-anchor" href="#_12-4-دع-ai-يلعب-دور-الجانب-المعارض" aria-label="Permalink to “12.4 دع AI يلعب دور &quot;الجانب المعارض&quot;”">​</a></h3><p>في كثير من الأحيان، نكون عاطفيين جدًا تجاه أفكارنا. يمكنك جعل AI يلعب خصمًا، يضغطك لتوضيح المشكلة بشكل أفضل:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>العب دور مستشار بحث منتجات صارم جدًا.</span></span>
<span class="line"><span>فيما يلي فرضية JTBD الخاصة بي: [فرضيتك]</span></span>
<span class="line"><span>انتقدها من الزوايا التالية:</span></span>
<span class="line"><span>1. هل هذا السيناريو واسع جدًا</span></span>
<span class="line"><span>2. هل هذه الوظيفة مكتوبة كوظيفة بدلاً من تقدم حقيقي</span></span>
<span class="line"><span>3. هل البديل ضعيف جدًا</span></span>
<span class="line"><span>4. هل معيار النجاح غير واضح بما فيه الكفاية</span></span>
<span class="line"><span>5. ما هو الخطر الذي يحتاج أكثر إلى التحقق في هذه الفرضية</span></span></code></pre></div><p>فائدة القيام بذلك هي أنك تستطيع اكتشاف بشكل أسرع ما إذا كنت تنظر إلى الاحتياج أم فقط إلى الحل الذي يعجبك.</p><h2 id="📚-الواجبات" tabindex="-1">📚 الواجبات <a class="header-anchor" href="#📚-الواجبات" aria-label="Permalink to “📚 الواجبات”">​</a></h2><p>يرجى إكمال الواجبات التالية بناءً على المحتوى أعلاه:</p><ol><li>اختر فكرة منتج تريد صنعها مؤخرًا، واكتبها بوضوح باستخدام صيغة JTBD</li><li>أكمل العناصر الخمسة لهذه الفكرة: السيناريو، المحفز، التقدم، البديل، معيار النجاح</li><li>ابحث عن 3 مستخدمين محتملين، واسأل على الأقل مرة &quot;متى واجهت هذه المشكلة آخر مرة&quot;</li><li>سلم الكلمات الأصلية للمقابلة إلى AI ونظمها في 3 فرضيات JTBD الأكثر استحقاقًا للتحقق أولاً</li></ol><h2 id="قراءة-إضافية" tabindex="-1">قراءة إضافية <a class="header-anchor" href="#قراءة-إضافية" aria-label="Permalink to “قراءة إضافية”">​</a></h2><ul><li><a href="https://www.christenseninstitute.org/theory/jobs-to-be-done/" target="_blank" rel="noreferrer">Christensen Institute: Jobs to Be Done</a></li><li><a href="https://online.hbs.edu/blog/post/jobs-to-be-done" target="_blank" rel="noreferrer">Harvard Business School Online: What Is Jobs to Be Done?</a></li><li><a href="https://www.intercom.com/blog/jobs-to-be-done-framework/" target="_blank" rel="noreferrer">Intercom: Jobs-to-be-Done: A framework for customer needs</a></li><li><a href="https://www.mural.co/blog/jobs-to-be-done-framework" target="_blank" rel="noreferrer">Mural: Jobs to Be Done framework guide</a></li></ul>`,147))])}}});export{g as __pageData,k as default};
